/// <summary>
/// Task 305538: PB033 -CB492 - PO status 'Invoiced is not appearing in Abbyy Open PO table (Bug - 290169) - D365 Build
/// </summary>
/// <returns></returns>
protected BusinessEventsBase getBusinessEvent()
{
    METPurchaseOrderInvoicedBusinessEvent businessEvent;

    if (targetSourceDocumentAccountingStatus == SourceDocumentAccountingStatus::Completed)
    {
        PurchTable          purchTable      = PurchTable::findSourceDocumentHeader(sourceDocumentHeader.RecId);
        VendInvoiceJour     vendInvoiceJour = VendInvoiceJour::findFromPurchId(purchTable.PurchId);

        METPurchaseOrderInvoicedBusinessEvent::construct(vendInvoiceJour, purchTable).send();
    }

    businessEvent = next getBusinessEvent();

    return businessEvent;
}
